def _segments(text,spans):
    out=[]
    for x in spans:
        if isinstance(x,str): out.append(x)
        elif isinstance(x,dict):
            if "text" in x: out.append(str(x.get("text","")))
            else:
                a=int(x.get("start",x.get("begin",0))); b=int(x.get("end",x.get("stop",a)))
                out.append(text[a:b])
        elif isinstance(x,(list,tuple)) and len(x)>=2: out.append(text[int(x[0]):int(x[1])])
        else: out.append("")
    return [x.lower() for x in out]

def _has(s,words):
    return any(w in s for w in words)

def _item(s):
    q=s.strip()
    return q.startswith(("(","•","","-")) or (len(q)>1 and q[0].isalnum() and q[1] in (".",")"))

def _head(out,xs,i,words):
    for j in reversed(range(i+1)):
        if _has(xs[j],words):
            out.add(j); return j
    return -1

def _defhead(out,xs,i):
    return _head(out,xs,i,("confidential information means","confidential information shall mean","proprietary information means","proprietary information shall mean","evaluation material means","information shall mean","information is defined as"))

def _exception(out,xs,i):
    return _head(out,xs,i,("shall not include","does not include","will not include","shall not apply","obligations shall not apply","restrictions shall not apply","does not extend to","inoperative as to","exceptions from","exclusions from"))

def propose_members(text,spans,public_hypothesis_key):
    xs=_segments(text,spans); out=set(); k=public_hypothesis_key
    for i,s in enumerate(xs):
        if k=="nda-11" and _has(s,("reverse engineer","reverse-engineer","decompile","de-compile","disassemble")):
            out.add(i)
        elif k=="nda-15" and _has(s,("no license","no licence","no right","no rights","does not grant","not be construed as granting","remain the property","remains the property","exclusive property","sole property","exclusive owner","retain all rights","reserves all rights","no title","no interest","does not acquire","not transferred","not convey","property of the disclos")):
            out.add(i)
        elif k=="nda-10" and _has(s,("existence of this agreement","existence and terms","existence or contents","terms of this agreement","fact that discussions","discussions or negotiations","discussions and negotiations","negotiations are taking place","subject matter or terms","public announcement concerning","public announcements concerning","transaction information","fact that information has been made available")):
            out.add(i)
        elif k=="nda-2":
            subjects=("business","financial","commercial","marketing","customer","client","supplier","employee","personnel","staff","operational","contractual","sales","distribution","costs","medical","genetic","patient","non-technical","all information")
            if _has(s,subjects) and (_has(s,("confidential information","proprietary information","evaluation material","shall include","includes, without","including, without")) or _item(s)):
                out.add(i); _defhead(out,xs,i)
        elif k=="nda-1" and _has(s,("marked","mark or label","designated","identified as","identified at","identify it in writing","reasonable person","reasonably understood","circumstances of disclosure","nature of the information","whether or not marked","need not be marked","does not need to be marked","specifically stated otherwise","list of confidential information")) and _has(s,("confidential","proprietary","information","disclos","list")):
            out.add(i); _defhead(out,xs,i)
        elif k=="nda-19" and (_has(s,("shall survive","will survive","survive termination","survive expiration","continue to be bound","continue in force","continue to apply","remain binding","after termination","beyond termination","continue beyond","notwithstanding the return","notwithstanding such return","unlimited in time","survive indefinitely")) or ("indefinitely" in s and _has(s,("obligation","agreement","confidential")))):
            out.add(i)
        elif k in ("nda-12","nda-13"):
            words=("independently developed","independent development","developed independently","independently derived","independently acquired","right to independently develop","developing information internally") if k=="nda-12" else ("from a third party","from third parties","third party having","third party who","another source","independent source","source other than","obtained from others","received from an independent","lawfully obtained","rightfully disclosed")
            if _has(s,words):
                out.add(i); _exception(out,xs,i)
        elif k=="nda-3" and _has(s,("oral","orally","verbally","uttered","spoken","whatever form","any form whatsoever","tangible or intangible","form or medium")) and _has(s,("information","disclos","communicat","confidential","proprietary","evaluation material")):
            out.add(i); _defhead(out,xs,i)
        elif k=="nda-17" and _has(s,("shall not copy","not copy","not reproduce","copy or reproduce","make copies","may make copies","copies required","copying","duplicate","reduce to writing","reproduce in any form")) and _has(s,("confidential","information","data","material","document","evaluation")):
            out.add(i)
        elif k=="nda-4" and _has(s,("solely for","only for","used solely","used only","no purpose other","not use","use only","except for the purpose","necessary for the purpose","sole purpose","for no other purpose")) and _has(s,("confidential","information","data","material","purpose","evaluation","project")):
            out.add(i)
    if k=="nda-16":
        acts=("return","destroy","delete","erase","deliver up","deliver back","surrender","disposal")
        objs=("information","data","material","document","copies","records")
        timing=("termination","expiration","completion","conclusion","assessment period","end of employment","end of the term","not wish to proceed","not consummated","ceasing to be interested")
        for i,s in enumerate(xs):
            if _has(s,acts) and _has(s,objs):
                for j in range(max(0,i-2),min(len(xs),i+3)):
                    if _has(xs[j],timing): out.update((i,j))
    elif k=="nda-20":
        retain=("retain one","may retain","entitled to retain","archival copy","archive copy","back-up","backup","not required to erase","not required to delete","infeasible","keep one copy","retain in the files","not obligated to return or destroy")
        found=False
        for i,s in enumerate(xs):
            if _has(s,retain):
                found=True; out.add(i); _head(out,xs,i,("notwithstanding","provided that","return or destruction","return of","disposal"))
        if not found:
            for i,s in enumerate(xs):
                if _has(s,("return","destroy","surrender","deliver back","disposal")) and _has(s,("information","data","material","document","copies","records")): out.add(i)
    elif k=="nda-18":
        verbs=("solicit","induce","entice","offer employment","offer to hire","employ or retain","contract for the services")
        actors=("employee","employment","personnel","representative","customer","client","services")
        for i,s in enumerate(xs):
            if _has(s,verbs):
                for j in range(max(0,i-2),min(len(xs),i+3)):
                    if _has(xs[j],actors): out.update((i,j))
    elif k=="nda-8":
        legal=("required by law","required to disclose","legally compelled","court order","subpoena","legal process","governmental authority","regulatory authority","judicial process","administrative process","operation of law")
        notice=("notice","notify","consult","inform","advise")
        for i,s in enumerate(xs):
            if _has(s,legal):
                for j in range(max(0,i-3),min(len(xs),i+4)):
                    if _has(xs[j],notice): out.update((i,j)); _exception(out,xs,i)
    elif k in ("nda-7","nda-5"):
        actors=("employee","employees","personnel","staff member") if k=="nda-5" else ("agent","consultant","advisor","adviser","counsel","accountant","contractor","subcontractor","representative","third party","professional adviser","authorised recipient","authorized recipient","affiliate")
        access=("disclose","disclosure","access","furnish","provide","share","supply","made available","need to know","may reveal","may discuss","kept secret from")
        chosen=[]
        for i,s in enumerate(xs):
            if _has(s,actors) and _has(s,access):
                chosen.append(i); out.add(i)
                if _item(s): _head(out,xs,i,("may disclose","permit access","permitted to disclose","disclosed only to","make available","disclosure to"))
        if any("representative" in xs[i] for i in chosen):
            for i,s in enumerate(xs):
                if _has(s,("representative means","representatives shall include","collectively, “representatives","collectively \"representatives")): out.add(i)
    return sorted(out)
